        canfd_frame.flags  = msg->flags;
        canfd_frame.len    = msg->data.length;
        memcpy(canfd_frame.data, msg->data.data, msg->data.length);

        ws_buffer_append(buf, (guint8 *)&canfd_frame, sizeof(canfd_frame));
    }
    else
